# Biology 3: biology and human welfare, biotechnology, and ecology and
# environment (NEET units 8 to 10). Key written first; numbers asserted.

# ten percent law: 10000 J at producers -> tertiary consumers (3 steps)
assert abs(10000 * 0.1 ** 3 - 10) < 1e-9

ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 2, "Malaria", "Which stage of Plasmodium enters the human body when an infected female Anopheles mosquito bites?",
      ["Sporozoite", "Gametocyte", "Merozoite", "Trophozoite"],
      "Sporozoites from the mosquito's salivary glands reach the liver and then the red blood cells. Gametocytes are the stage the mosquito picks up from human blood."),
    S(1, 2, "Immunity", "Which class of antibody can cross the placenta from mother to foetus?",
      ["IgG", "IgA", "IgM", "IgE"],
      "IgG crosses the placenta and gives the newborn passive immunity. IgA reaches the baby in colostrum, and IgE is involved in allergies."),
    S(1, 1, "AIDS", "Which cells does HIV mainly infect and destroy?",
      ["Helper T cells", "B cells", "Red blood cells", "Platelets"],
      "HIV enters macrophages, which keep making virus, and then helper T lymphocytes (T₄ or CD4 cells), whose numbers fall steadily, weakening immunity."),
    S(1, 2, "Biofertilisers", "Which of these is a free-living, nitrogen-fixing bacterium used as a biofertiliser?",
      ["Azotobacter", "Rhizobium", "Glomus", "Lactobacillus"],
      "Azotobacter and Azospirillum fix nitrogen while free-living in the soil. Rhizobium fixes nitrogen only in the root nodules of legumes, and Glomus is a mycorrhizal fungus."),
    S(1, 2, "Sewage treatment", "In the secondary (biological) treatment of sewage, what are the flocs that form in the aeration tanks?",
      ["Bacteria bound by fungal filaments", "Clumps of grit and sand", "Algae grown in settling tanks", "Lumps of chemical coagulant"],
      "Aerobic microbes grow into flocs, masses of bacteria held together by fungal filaments, which consume much of the organic matter. Grit and sand are removed earlier, in primary treatment."),
    S(1, 3, "Restriction enzymes", "EcoRI recognises the sequence 5'-GAATTC-3'. Between which two bases does it cut each strand?",
      ["G and A", "A and T", "T and C", "A and A"],
      "EcoRI cuts between G and A on both strands, which leaves single-stranded AATT overhangs, the sticky ends that pair with any fragment cut by the same enzyme."),
    S(1, 1, "Recombinant DNA", "Which enzyme joins DNA fragments in recombinant DNA technology?",
      ["DNA ligase", "Exonuclease", "DNA polymerase", "Restriction enzyme"],
      "DNA ligase seals the sugar-phosphate backbone between fragments with matching sticky ends. Restriction enzymes do the cutting."),
    S(1, 2, "Bt crops", "Why does the Bt toxin kill insect larvae without harming the bacterium that makes it?",
      ["The larva's alkaline gut activates it", "The larva's acidic gut activates it", "The bacterium is immune to all toxins", "Only insect cells can take it up"],
      "Bacillus thuringiensis stores the toxin as an inactive protoxin. In the alkaline gut of the larva it is converted to the active form, which binds the midgut cells and makes pores that kill the insect."),
    S(1, 2, "Population interactions", "The koel (cuckoo) lays its eggs in the nest of the crow, and the crow incubates them and raises the young. What is this interaction called?",
      ["Brood parasitism", "Commensalism", "Mutualism", "Competition"],
      "The cuckoo gains while the host crow spends its effort raising another species' young, so it is parasitism; the parasite's eggs have evolved to look like the host's. In commensalism the other species would be unaffected."),
    S(1, 2, "Energy flow", "Producers in a food chain fix 10,000 J of energy. By the 10 percent law, how much reaches the tertiary consumers?",
      ["10 J", "100 J", "1 J", "1000 J"],
      "Only about 10% passes to each higher level: 1000 J to primary, 100 J to secondary and 10 J to tertiary consumers. 100 J stops one level too early."),
    # ---------- Practice Test 2 ----------
    S(2, 2, "Human diseases", "In which disease do houseflies act as mechanical carriers of the parasite from faeces to food and water?",
      ["Amoebiasis", "Malaria", "Filariasis", "Pneumonia"],
      "Amoebiasis (amoebic dysentery) is caused by the protozoan Entamoeba histolytica in the large intestine, and houseflies carry it to food. Malaria and filariasis are spread by mosquitoes, and pneumonia by droplets."),
    S(2, 2, "Typhoid", "Which test is used to confirm typhoid fever?",
      ["Widal test", "ELISA", "Mantoux test", "Western blot"],
      "The Widal test detects antibodies against Salmonella typhi in the blood. ELISA is used for HIV, and the Mantoux test for tuberculosis."),
    S(2, 2, "Cancer", "Which property of normal cells is lost in cancer cells, so that they keep dividing when they touch other cells?",
      ["Contact inhibition", "Cell division", "Protein synthesis", "Membrane transport"],
      "Contact with other cells normally stops cell division. Cancer cells lose this, so they divide without limit and form masses called tumours."),
    S(2, 2, "Microbes in industry", "Statins, which lower blood cholesterol, are produced commercially from which microbe?",
      ["Monascus purpureus", "Trichoderma polysporum", "Aspergillus niger", "Streptococcus"],
      "Monascus purpureus makes statins, which competitively inhibit the enzyme that makes cholesterol. Trichoderma polysporum gives cyclosporin A, and Aspergillus niger citric acid."),
    S(2, 3, "Human insulin", "How were the A and B chains of the first genetically engineered human insulin produced?",
      ["Made separately, then joined", "Made together as proinsulin", "Extracted from cattle pancreas", "Synthesised chemically in vitro"],
      "DNA for each chain was put into E. coli separately; the chains were extracted and linked by disulphide bonds to form insulin, so no C peptide had to be removed."),
    S(2, 2, "PCR", "Why is Taq polymerase used in the polymerase chain reaction?",
      ["It stays active at high temperature", "It needs no primers to start", "It cuts DNA at specific sites", "It joins Okazaki fragments"],
      "Taq polymerase comes from Thermus aquaticus, a bacterium of hot springs, so it survives the repeated high-temperature denaturation steps of PCR."),
    S(2, 1, "Gel electrophoresis", "After agarose gel electrophoresis, separated DNA bands are stained with ethidium bromide. How are they then seen?",
      ["As orange bands under UV light", "As blue bands in daylight", "As dark bands under X-rays", "As green bands under a lamp"],
      "Ethidium bromide slips between the DNA bases and glows orange under ultraviolet light, so the bands show up when the gel is put on a UV transilluminator."),
    S(2, 2, "Population growth", "A population grows in a habitat with limited resources. Which growth curve does it follow?",
      ["Sigmoid", "Exponential", "Linear", "Bell-shaped"],
      "Growth is slow at first, then fast, and then levels off at the carrying capacity K, giving the S-shaped logistic (Verhulst-Pearl) curve. A J-shaped exponential curve needs unlimited resources."),
    S(2, 2, "Ecological pyramids", "Which ecological pyramid is always upright?",
      ["Pyramid of energy", "Pyramid of biomass", "Pyramid of numbers", "Age pyramid"],
      "Energy always falls from one trophic level to the next, so the pyramid of energy can never be inverted. The biomass pyramid in the sea and the number pyramid of a tree can be."),
    S(2, 1, "Biodiversity conservation", "Sacred groves protected by communities are an example of:",
      ["In situ conservation", "Ex situ conservation", "Cryopreservation", "Seed banking"],
      "Sacred groves protect species in their natural habitat, as do national parks and biosphere reserves. Zoos, botanical gardens and seed banks are ex situ."),
    # ---------- Drill only ----------
    S(0, 2, "Vaccines", "The hepatitis B vaccine is produced from:",
      ["Recombinant yeast", "Attenuated virus", "Killed bacteria", "Horse serum"],
      "The gene for the hepatitis B surface antigen is expressed in yeast, and the purified protein is used as the vaccine. It is an example of recombinant DNA technology."),
    L(0, 2, "Biopiracy and patents", "Statement I: Biopiracy is the use of bio-resources under an agreed benefit-sharing contract with the countries and people concerned.\n\nStatement II: Patents can never be granted for any product made using a living organism.\n\nChoose the correct answer:",
      ST, 1,
      "Both are false. Biopiracy is the use of bio-resources without proper authorisation or compensation, not under an agreed contract. Patents have been granted for products and processes based on biological resources, which is why biopiracy is a concern."),
    S(0, 2, "Productivity", "The rate at which producers make biomass by photosynthesis is called:",
      ["Primary productivity", "Secondary productivity", "Standing crop", "Decomposition rate"],
      "Gross primary productivity is the total rate; net primary productivity subtracts the producers' respiration losses. Standing crop is the biomass present at one moment."),
    S(0, 2, "Biodiversity conservation", "How many of these are ex situ methods of conservation?\n\nZoological park, botanical garden, sacred grove, national park, seed bank",
      ["3", "2", "4", "1"],
      "Zoological parks, botanical gardens and seed banks keep organisms away from their natural habitat. Sacred groves and national parks protect them where they live."),
]
